CREATE PROCEDURE TEST.DYNAMIC_VARIANT_BUDGET
(
    IN P1 INTEGER,
    OUT P_RESULT INTEGER
)
LANGUAGE SQL
BEGIN
    DECLARE V_SQL VARCHAR(1000) DEFAULT 'UPDATE T0 SET C = 0';
    IF P1 = 1 THEN SET V_SQL = 'UPDATE T1 SET C = 1'; END IF;
    IF P1 = 2 THEN SET V_SQL = 'UPDATE T2 SET C = 2'; END IF;
    IF P1 = 3 THEN SET V_SQL = 'UPDATE T3 SET C = 3'; END IF;
    IF P1 = 4 THEN SET V_SQL = 'UPDATE T4 SET C = 4'; END IF;
    IF P1 = 5 THEN SET V_SQL = 'UPDATE T5 SET C = 5'; END IF;
    IF P1 = 6 THEN SET V_SQL = 'UPDATE T6 SET C = 6'; END IF;
    IF P1 = 7 THEN SET V_SQL = 'UPDATE T7 SET C = 7'; END IF;
    IF P1 = 8 THEN SET V_SQL = 'UPDATE T8 SET C = 8'; END IF;
    IF P1 = 9 THEN SET V_SQL = 'UPDATE T9 SET C = 9'; END IF;
    IF P1 = 10 THEN SET V_SQL = 'UPDATE T10 SET C = 10'; END IF;
    IF P1 = 11 THEN SET V_SQL = 'UPDATE T11 SET C = 11'; END IF;
    EXECUTE IMMEDIATE V_SQL;
    SET P_RESULT = 1;
END;
